record.field:
rental_lines = self.filtered(lambda line: line.x_rental_date_start and line.x_rental_date_stop and line.x_resource_ids)
if rental_lines:
    for line in rental_lines:
        query = """
            SELECT
              x_resource_id AS resource_id,
              count(*) AS overlap_count
            FROM x_rental_booking
            WHERE
              x_resource_id IN %s
              AND TSRANGE(x_date_start, x_date_stop, '[]') && TSRANGE(%s::timestamp, %s::timestamp, '[]')
              AND x_status != 'cancelled'
            GROUP BY x_resource_id
        """
        self.env.cr.execute(query, (tuple(line.x_resource_ids.ids), line.x_rental_date_start, line.x_rental_date_stop),)
        count_map = {item['resource_id']: item['overlap_count'] for item in self.env.cr.dictfetchall()}
        if count_map:
            resource_map = {r.id: r.name for r in self.env['resource.resource'].browse(list(count_map))}
            line['x_rental_overlap_message'] =  "\n".join([f"{resource_map[k]} has already {v} rental booking(s) during the chosen period." for k,v in count_map.items()])
        else:
            line['x_rental_overlap_message'] = None
else:
    for line in self - rental_lines:
        line['x_rental_overlap_message'] = None
